-- Authova PostgreSQL 17+ core identity schema design draft, 2026-10-11.
-- Review artifact only: not a numbered production migration.
-- UUIDs are generated by the Go application; timestamps are stored in UTC.
-- Secret ciphertext requires an external envelope key provider.

CREATE TABLE apps (
    id uuid PRIMARY KEY,
    app_key text NOT NULL UNIQUE,
    slug text NOT NULL UNIQUE,
    display_name text NOT NULL,
    issuer text NOT NULL UNIQUE,
    status text NOT NULL CHECK (status IN ('provisioning','active','suspended','deleting','deleted')),
    config_version bigint NOT NULL DEFAULT 1 CHECK (config_version > 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (app_key ~ '^[a-z0-9]{12,64}$'),
    CHECK (slug ~ '^[a-z][a-z0-9-]*[a-z0-9]$' AND char_length(slug) BETWEEN 3 AND 63)
);

CREATE TABLE app_signing_keys (
    app_id uuid NOT NULL REFERENCES apps(id),
    id uuid NOT NULL,
    kid text NOT NULL,
    algorithm text NOT NULL,
    key_ref text NOT NULL,
    public_jwk jsonb NOT NULL,
    status text NOT NULL CHECK (status IN ('prepared','signing','verifying','retired','compromised')),
    not_before timestamptz NOT NULL,
    stop_signing_at timestamptz,
    stop_verifying_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (app_id,id),
    UNIQUE (app_id,kid),
    CHECK (stop_verifying_at IS NULL OR stop_verifying_at > not_before)
);
CREATE UNIQUE INDEX one_signing_key_per_app ON app_signing_keys(app_id)
    WHERE status = 'signing';

CREATE TABLE platform_operators (
    id uuid PRIMARY KEY,
    email_lookup_digest bytea NOT NULL UNIQUE,
    email_ciphertext bytea NOT NULL,
    password_verifier text,
    totp_secret_ciphertext bytea,
    status text NOT NULL CHECK (status IN ('pending_mfa','active','suspended')),
    session_epoch bigint NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (status <> 'active' OR
           (password_verifier IS NOT NULL AND totp_secret_ciphertext IS NOT NULL))
);

-- Insert the singleton and initial operator in one transaction. The primary
-- key makes concurrent bootstrap attempts serialize at the database boundary.
CREATE TABLE platform_bootstrap_guard (
    singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
    initial_operator_id uuid NOT NULL UNIQUE REFERENCES platform_operators(id),
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE platform_activation_challenges (
    id uuid PRIMARY KEY,
    operator_id uuid NOT NULL REFERENCES platform_operators(id),
    challenge_digest bytea NOT NULL UNIQUE CHECK (octet_length(challenge_digest)=32),
    status text NOT NULL CHECK (status IN ('issued','consumed','expired')),
    expires_at timestamptz NOT NULL,
    consumed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX platform_activation_expiry ON platform_activation_challenges(expires_at);

CREATE TABLE platform_operator_roles (
    operator_id uuid NOT NULL REFERENCES platform_operators(id),
    role text NOT NULL CHECK (role IN ('owner','admin','auditor')),
    granted_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (operator_id,role)
);

CREATE TABLE platform_sessions (
    id uuid PRIMARY KEY,
    operator_id uuid NOT NULL REFERENCES platform_operators(id),
    handle_digest bytea NOT NULL UNIQUE,
    authenticated_at timestamptz NOT NULL,
    mfa_at timestamptz NOT NULL,
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX platform_sessions_by_operator ON platform_sessions(operator_id,expires_at);

CREATE TABLE platform_signing_keys (
    id uuid PRIMARY KEY,
    kid text NOT NULL UNIQUE,
    algorithm text NOT NULL,
    key_ref text NOT NULL,
    public_jwk jsonb NOT NULL,
    status text NOT NULL CHECK (status IN ('prepared','signing','verifying','retired','compromised')),
    not_before timestamptz NOT NULL,
    stop_verifying_at timestamptz
);
CREATE UNIQUE INDEX one_platform_signing_key ON platform_signing_keys(status)
    WHERE status='signing';

CREATE TABLE platform_clients (
    id uuid PRIMARY KEY,
    client_id text NOT NULL UNIQUE CHECK (client_id ~ '^avp_[a-z0-9]{26}$'),
    redirect_uri text NOT NULL,
    require_pkce boolean NOT NULL DEFAULT true CHECK (require_pkce),
    status text NOT NULL CHECK (status IN ('active','disabled')),
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE platform_auth_flows (
    id uuid PRIMARY KEY,
    client_pk uuid NOT NULL REFERENCES platform_clients(id),
    operator_id uuid REFERENCES platform_operators(id),
    browser_binding_digest bytea NOT NULL,
    csrf_digest bytea NOT NULL,
    redirect_uri text NOT NULL,
    pkce_challenge text NOT NULL,
    oidc_nonce text,
    status text NOT NULL CHECK (status IN ('started','authenticated','completed','cancelled')),
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX platform_auth_flows_expiry ON platform_auth_flows(expires_at);

CREATE TABLE platform_auth_codes (
    id uuid PRIMARY KEY,
    code_digest bytea NOT NULL UNIQUE,
    client_pk uuid NOT NULL REFERENCES platform_clients(id),
    operator_id uuid NOT NULL REFERENCES platform_operators(id),
    session_id uuid NOT NULL REFERENCES platform_sessions(id),
    redirect_uri text NOT NULL,
    pkce_challenge text NOT NULL,
    oidc_nonce text,
    status text NOT NULL CHECK (status IN ('issued','consumed')),
    expires_at timestamptz NOT NULL,
    consumed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX platform_auth_codes_expiry ON platform_auth_codes(expires_at);

CREATE TABLE clients (
    app_id uuid NOT NULL REFERENCES apps(id),
    id uuid NOT NULL,
    client_id text NOT NULL UNIQUE CHECK (client_id ~ '^avc_[a-z0-9]{26}$'),
    display_name text NOT NULL,
    is_system boolean NOT NULL DEFAULT false,
    kind text NOT NULL CHECK (kind IN ('public','confidential')),
    status text NOT NULL CHECK (status IN ('active','disabled')),
    token_endpoint_auth_method text NOT NULL CHECK (token_endpoint_auth_method IN ('none','client_secret_basic')),
    require_pkce boolean NOT NULL DEFAULT true,
    allowed_grants text[] NOT NULL,
    allowed_scopes text[] NOT NULL,
    allowed_audiences text[] NOT NULL,
    allowed_introspection_audiences text[] NOT NULL DEFAULT '{}',
    config_version bigint NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (app_id,id),
    CHECK (kind='confidential' OR cardinality(allowed_introspection_audiences)=0),
    CHECK ((kind='public' AND token_endpoint_auth_method='none') OR
           (kind='confidential' AND token_endpoint_auth_method<>'none'))
);
CREATE INDEX clients_by_app_status ON clients(app_id,status,id);

CREATE TABLE client_redirect_uris (
    app_id uuid NOT NULL,
    client_pk uuid NOT NULL,
    redirect_uri text NOT NULL,
    PRIMARY KEY (app_id,client_pk,redirect_uri),
    FOREIGN KEY (app_id,client_pk) REFERENCES clients(app_id,id) ON DELETE CASCADE
);

CREATE TABLE client_secrets (
    app_id uuid NOT NULL,
    id uuid NOT NULL,
    client_pk uuid NOT NULL,
    verifier_digest bytea NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz,
    revoked_at timestamptz,
    PRIMARY KEY (app_id,id),
    FOREIGN KEY (app_id,client_pk) REFERENCES clients(app_id,id) ON DELETE CASCADE
);
CREATE INDEX client_secrets_active ON client_secrets(app_id,client_pk,expires_at)
    WHERE revoked_at IS NULL;

CREATE TABLE users (
    app_id uuid NOT NULL REFERENCES apps(id),
    id uuid NOT NULL,
    status text NOT NULL CHECK (status IN ('active','disabled','deleting','deleted')),
    profile_ciphertext bytea,
    profile_version bigint NOT NULL DEFAULT 1,
    session_epoch bigint NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    PRIMARY KEY (app_id,id)
);
CREATE INDEX users_by_app_created ON users(app_id,created_at,id);

CREATE TABLE user_identifiers (
    app_id uuid NOT NULL,
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL CHECK (kind IN ('email','phone')),
    normalization_version smallint NOT NULL,
    lookup_key_version smallint NOT NULL,
    lookup_digest bytea NOT NULL,
    value_ciphertext bytea NOT NULL,
    status text NOT NULL CHECK (status IN ('active','retired')),
    verified_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    retired_at timestamptz,
    PRIMARY KEY (app_id,id),
    UNIQUE (app_id,id,kind),
    FOREIGN KEY (app_id,user_id) REFERENCES users(app_id,id),
    CHECK (octet_length(lookup_digest)=32),
    CHECK ((status='active' AND retired_at IS NULL) OR
           (status='retired' AND retired_at IS NOT NULL))
);
CREATE UNIQUE INDEX identifier_active_unique
    ON user_identifiers(app_id,kind,lookup_digest) WHERE status='active';
CREATE INDEX identifiers_by_user ON user_identifiers(app_id,user_id,status);

-- Active lookup aliases permit online HMAC key rotation. Each active
-- identifier has one alias per currently accepted lookup key version.
CREATE TABLE identifier_lookup_aliases (
    app_id uuid NOT NULL,
    identifier_id uuid NOT NULL,
    kind text NOT NULL CHECK (kind IN ('email','phone')),
    lookup_key_version smallint NOT NULL,
    lookup_digest bytea NOT NULL CHECK (octet_length(lookup_digest)=32),
    PRIMARY KEY (app_id,kind,lookup_key_version,lookup_digest),
    UNIQUE (app_id,identifier_id,lookup_key_version),
    FOREIGN KEY (app_id,identifier_id,kind) REFERENCES user_identifiers(app_id,id,kind)
);

CREATE TABLE password_credentials (
    app_id uuid NOT NULL,
    user_id uuid NOT NULL,
    verifier text NOT NULL,
    pepper_key_ref text,
    changed_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (app_id,user_id),
    FOREIGN KEY (app_id,user_id) REFERENCES users(app_id,id)
);

CREATE TABLE provider_connections (
    app_id uuid NOT NULL REFERENCES apps(id),
    id uuid NOT NULL,
    name text NOT NULL,
    kind text NOT NULL CHECK (kind IN ('oidc','custom_adapter')),
    upstream_issuer text,
    secret_ref text,
    config_ciphertext bytea NOT NULL,
    status text NOT NULL CHECK (status IN ('draft','active','disabled')),
    config_version bigint NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (app_id,id),
    UNIQUE (app_id,name)
);

CREATE TABLE external_identities (
    app_id uuid NOT NULL,
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    upstream_issuer text NOT NULL,
    upstream_subject_ciphertext bytea NOT NULL,
    upstream_subject_digest bytea NOT NULL CHECK (octet_length(upstream_subject_digest)=32),
    linked_at timestamptz NOT NULL DEFAULT now(),
    unlinked_at timestamptz,
    PRIMARY KEY (app_id,id),
    UNIQUE (app_id,id,connection_id),
    FOREIGN KEY (app_id,user_id) REFERENCES users(app_id,id),
    FOREIGN KEY (app_id,connection_id) REFERENCES provider_connections(app_id,id)
);
CREATE UNIQUE INDEX external_identity_active_unique
    ON external_identities(app_id,connection_id,upstream_subject_digest)
    WHERE unlinked_at IS NULL;
CREATE INDEX external_identities_by_user ON external_identities(app_id,user_id)
    WHERE unlinked_at IS NULL;

CREATE TABLE external_identity_lookup_aliases (
    app_id uuid NOT NULL,
    identity_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    lookup_key_version smallint NOT NULL,
    subject_digest bytea NOT NULL CHECK (octet_length(subject_digest)=32),
    PRIMARY KEY (app_id,connection_id,lookup_key_version,subject_digest),
    UNIQUE (app_id,identity_id,lookup_key_version),
    FOREIGN KEY (app_id,identity_id,connection_id) REFERENCES external_identities(app_id,id,connection_id)
);

CREATE TABLE auth_challenges (
    app_id uuid NOT NULL REFERENCES apps(id),
    id uuid NOT NULL,
    user_id uuid,
    purpose text NOT NULL CHECK (purpose IN ('register','login','reset_password','change_identifier','bind_external')),
    destination_digest bytea,
    code_digest bytea NOT NULL,
    attempts smallint NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    status text NOT NULL CHECK (status IN ('issued','consumed','locked')),
    expires_at timestamptz NOT NULL,
    consumed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (app_id,id),
    FOREIGN KEY (app_id,user_id) REFERENCES users(app_id,id)
);
CREATE INDEX auth_challenges_expiry ON auth_challenges(expires_at);

CREATE TABLE auth_flows (
    app_id uuid NOT NULL REFERENCES apps(id),
    id uuid NOT NULL,
    flow_type text NOT NULL CHECK (flow_type IN ('authorize','recover','bind_external','change_identifier')),
    client_pk uuid,
    connection_id uuid,
    user_id uuid,
    browser_binding_digest bytea NOT NULL,
    csrf_digest bytea NOT NULL,
    upstream_state_digest bytea,
    upstream_nonce text,
    requested_scopes text[] NOT NULL DEFAULT '{}',
    requested_audiences text[] NOT NULL DEFAULT '{}',
    redirect_uri text,
    pkce_challenge text,
    current_step text NOT NULL CHECK (current_step IN ('choose_method','identify','verify_identifier','password','set_password','mfa','consent','federation','recovery','complete')),
    auth_time timestamptz,
    mfa_time timestamptz,
    status text NOT NULL CHECK (status IN ('started','authenticated','completed','cancelled')),
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (app_id,id),
    FOREIGN KEY (app_id,client_pk) REFERENCES clients(app_id,id),
    FOREIGN KEY (app_id,connection_id) REFERENCES provider_connections(app_id,id),
    FOREIGN KEY (app_id,user_id) REFERENCES users(app_id,id)
);
CREATE INDEX auth_flows_expiry ON auth_flows(expires_at);
CREATE UNIQUE INDEX auth_flows_upstream_state ON auth_flows(app_id,upstream_state_digest)
    WHERE upstream_state_digest IS NOT NULL;

CREATE TABLE sessions (
    app_id uuid NOT NULL,
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    handle_digest bytea NOT NULL,
    auth_time timestamptz NOT NULL,
    mfa_time timestamptz,
    session_epoch bigint NOT NULL,
    expires_at timestamptz NOT NULL,
    last_seen_at timestamptz NOT NULL,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (app_id,id),
    FOREIGN KEY (app_id,user_id) REFERENCES users(app_id,id),
    UNIQUE (app_id,handle_digest)
);
CREATE INDEX sessions_by_user ON sessions(app_id,user_id,expires_at)
    WHERE revoked_at IS NULL;

CREATE TABLE auth_codes (
    app_id uuid NOT NULL,
    id uuid NOT NULL,
    code_digest bytea NOT NULL,
    client_pk uuid NOT NULL,
    user_id uuid NOT NULL,
    session_id uuid NOT NULL,
    redirect_uri text NOT NULL,
    pkce_challenge text NOT NULL,
    oidc_nonce text,
    granted_scopes text[] NOT NULL,
    granted_audiences text[] NOT NULL,
    status text NOT NULL CHECK (status IN ('issued','consumed')),
    expires_at timestamptz NOT NULL,
    consumed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (app_id,id),
    UNIQUE (app_id,code_digest),
    FOREIGN KEY (app_id,client_pk) REFERENCES clients(app_id,id),
    FOREIGN KEY (app_id,user_id) REFERENCES users(app_id,id),
    FOREIGN KEY (app_id,session_id) REFERENCES sessions(app_id,id)
);
CREATE INDEX auth_codes_expiry ON auth_codes(expires_at);

CREATE TABLE oauth_consents (
    app_id uuid NOT NULL,
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    client_pk uuid NOT NULL,
    granted_scopes text[] NOT NULL,
    granted_audiences text[] NOT NULL,
    terms_version text,
    status text NOT NULL CHECK (status IN ('active','revoked')),
    granted_at timestamptz NOT NULL,
    revoked_at timestamptz,
    PRIMARY KEY (app_id,id),
    FOREIGN KEY (app_id,user_id) REFERENCES users(app_id,id),
    FOREIGN KEY (app_id,client_pk) REFERENCES clients(app_id,id)
);
CREATE UNIQUE INDEX oauth_consent_active_unique
    ON oauth_consents(app_id,user_id,client_pk) WHERE status='active';

CREATE TABLE refresh_families (
    app_id uuid NOT NULL,
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    client_pk uuid NOT NULL,
    session_id uuid NOT NULL,
    generation bigint NOT NULL DEFAULT 0,
    granted_scopes text[] NOT NULL,
    granted_audiences text[] NOT NULL,
    status text NOT NULL CHECK (status IN ('active','revoked','expired')),
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    last_used_at timestamptz,
    revoked_at timestamptz,
    PRIMARY KEY (app_id,id),
    FOREIGN KEY (app_id,user_id) REFERENCES users(app_id,id),
    FOREIGN KEY (app_id,client_pk) REFERENCES clients(app_id,id),
    FOREIGN KEY (app_id,session_id) REFERENCES sessions(app_id,id)
);
CREATE INDEX refresh_families_by_session ON refresh_families(app_id,session_id,status);

CREATE TABLE refresh_tokens (
    app_id uuid NOT NULL,
    id uuid NOT NULL,
    family_id uuid NOT NULL,
    generation bigint NOT NULL,
    token_digest bytea NOT NULL,
    status text NOT NULL CHECK (status IN ('active','used','revoked')),
    issued_at timestamptz NOT NULL DEFAULT now(),
    used_at timestamptz,
    expires_at timestamptz NOT NULL,
    PRIMARY KEY (app_id,id),
    FOREIGN KEY (app_id,family_id) REFERENCES refresh_families(app_id,id),
    UNIQUE (app_id,token_digest),
    UNIQUE (app_id,family_id,generation)
);
CREATE INDEX refresh_tokens_by_family ON refresh_tokens(app_id,family_id,status);
CREATE INDEX refresh_tokens_expiry ON refresh_tokens(expires_at);

CREATE TABLE app_admin_grants (
    app_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text NOT NULL CHECK (role IN ('owner','admin','auditor')),
    granted_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (app_id,user_id,role),
    FOREIGN KEY (app_id,user_id) REFERENCES users(app_id,id)
);

CREATE TABLE audit_events (
    id uuid PRIMARY KEY,
    app_id uuid REFERENCES apps(id),
    actor_kind text NOT NULL,
    actor_id text,
    event_type text NOT NULL,
    target_kind text,
    target_id text,
    result text NOT NULL CHECK (result IN ('success','denied','error')),
    request_id text,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_by_app_time ON audit_events(app_id,occurred_at DESC,id);
CREATE INDEX audit_by_type_time ON audit_events(event_type,occurred_at DESC);

CREATE TABLE outbox_events (
    id uuid PRIMARY KEY,
    app_id uuid REFERENCES apps(id),
    event_type text NOT NULL,
    schema_version integer NOT NULL,
    payload jsonb NOT NULL,
    sensitive_payload_ciphertext bytea,
    status text NOT NULL CHECK (status IN ('pending','delivering','delivered','dead')),
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    available_at timestamptz NOT NULL DEFAULT now(),
    created_at timestamptz NOT NULL DEFAULT now(),
    delivered_at timestamptz
);
CREATE INDEX outbox_pending ON outbox_events(available_at,id)
    WHERE status IN ('pending','delivering');

CREATE TABLE idempotency_records (
    scope_kind text NOT NULL CHECK (scope_kind IN ('app','platform')),
    app_id uuid REFERENCES apps(id),
    scope_key text NOT NULL,
    principal_key text NOT NULL,
    operation text NOT NULL,
    idem_key uuid NOT NULL,
    request_digest bytea NOT NULL,
    status text NOT NULL CHECK (status IN ('in_progress','completed')),
    response_status integer,
    response_body jsonb,
    response_ciphertext bytea,
    secret_replay_expires_at timestamptz,
    resource_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    PRIMARY KEY (scope_key,principal_key,operation,idem_key),
    CHECK (octet_length(request_digest)=32),
    CHECK (response_body IS NULL OR response_ciphertext IS NULL),
    CHECK (response_ciphertext IS NULL OR secret_replay_expires_at IS NOT NULL),
    CHECK ((scope_kind='app' AND app_id IS NOT NULL) OR
           (scope_kind='platform' AND app_id IS NULL))
);
CREATE INDEX idempotency_expiry ON idempotency_records(expires_at);

-- Production RLS policies are in rls-v1.sql. This example alone does not
-- protect the full schema:
-- ALTER TABLE users ENABLE ROW LEVEL SECURITY;
-- ALTER TABLE users FORCE ROW LEVEL SECURITY;
-- CREATE POLICY app_users ON users
--   USING (app_id = NULLIF(current_setting('authova.app_id', true),'')::uuid)
--   WITH CHECK (app_id = NULLIF(current_setting('authova.app_id', true),'')::uuid);
